   189	func writeFileAtomic(path string, data []byte, perm os.FileMode) error {
   190		if err := os.MkdirAll(filepath.Dir(path), 0o700); err != nil {
   191			return err
   192		}
   193		tmp, err := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+".tmp-*")
   194		if err != nil {
   195			return err
   196		}
   197		tmpName := tmp.Name()
   198		cleanup := true
   199		defer func() {
   200			if cleanup {
   201				_ = os.Remove(tmpName)
   202			}
   203		}()
   204		if _, err := tmp.Write(data); err != nil {
   205			_ = tmp.Close()
   206			return err
   207		}
   208		if err := tmp.Chmod(perm); err != nil {
   209			_ = tmp.Close()
   210			return err
   211		}
   212		if err := tmp.Close(); err != nil {
   213			return err
   214		}
   215		if err := os.Rename(tmpName, path); err != nil {
   216			return err
   217		}
   218		cleanup = false
   219		return nil
   220	}
