  1022			}
  1023			return now.Add(-time.Duration(days) * 24 * time.Hour), nil
  1024		}
  1025		duration, err := time.ParseDuration(value)
  1026		if err != nil {
  1027			return time.Time{}, fmt.Errorf("invalid --older-than value: %s", value)
  1028		}
  1029		return now.Add(-duration), nil
  1030	}
